  function getPopularProducts(){const available=products.filter(p=>p.available!==false);const counts={};orders.forEach(o=>(o.items||[]).forEach(i=>{counts[i.id]=(counts[i.id]||0)+Number(i.qty||1);}));const ordered=available.slice().sort((a,b)=>(counts[b.id]||0)-(counts[a.id]||0));if(available.some(p=>counts[p.id]))return ordered.filter(p=>(counts[p.id]||0)>0).slice(0,3);const featured=available.filter(p=>p.featured);return (featured.length?featured:available).slice(0,3);}
  function renderPopular(){const slides=$('#popular-slides'),dots=$('#popular-dots');if(!slides||!dots)return;const list=getPopularProducts();if(!list.length){slides.innerHTML='<div class="popular-empty">ستظهر هنا الأطباق المميزة عند إضافة المنتجات.</div>';dots.innerHTML='';return;}popularIndex=((popularIndex%list.length)+list.length)%list.length;const p=list[popularIndex];slides.innerHTML=`<article class="popular-slide" style="--slide-image:url('${esc(p.image||'')}')"><div class="popular-image">${`<img src="${esc(p.image||productImageFallback(p.category))}" data-fallback="${esc(productImageFallback(p.category))}" alt="${esc(p.name)}" loading="eager" decoding="async" onerror="if(this.dataset.fallbackApplied!=='1'){this.dataset.fallbackApplied='1';this.src=this.dataset.fallback;}else{this.onerror=null;this.classList.add('image-failed');}">`}</div><div class="popular-copy"><span class="popular-kicker">${orders.some(o=>(o.items||[]).some(i=>i.id===p.id))?'اختيار الأكثر طلباً':'اختيار مميز من الشيف'}</span><h3>${esc(language==='en'?(p.nameEn||p.name):p.name)}</h3><p>${esc(language==='en'?(p.descriptionEn||p.description||'Chef’s special.'):p.description||'طبق مميز من اختيار الشيف.')}</p><div class="popular-price">${priceMarkup(p)}</div><div class="popular-actions"><button class="btn btn-primary" data-action="add" data-id="${esc(p.id)}">${language==='en'?'Add to cart +':'أضف إلى السلة +'}</button><a class="btn btn-ghost" href="menu.html">${language==='en'?'Explore menu':'اكتشف القائمة'}</a></div></div></article>`;dots.innerHTML=list.map((x,i)=>`<button type="button" class="popular-dot ${i===popularIndex?'active':''}" data-action="popular-go" data-index="${i}" aria-label="عرض ${esc(x.name)}" aria-current="${i===popularIndex?'true':'false'}"></button>`).join('');}
  function shiftPopular(step){const list=getPopularProducts();if(!list.length)return;popularIndex=(popularIndex+step+list.length)%list.length;renderPopular();}
  function renderHome(){const grid=$('#featured-grid');if(grid){const available=products.filter(p=>p.available);grid.innerHTML=(available.filter(p=>p.featured).slice(0,4).length?available.filter(p=>p.featured).slice(0,4):available.slice(0,4)).map(productCard).join('')||'<div class="empty-state">لا توجد أصناف متاحة حالياً.</div>'; }const hero=$('#home-hero-image');if(hero){const heroProduct=products.find(p=>p.featured&&p.image)||products.find(p=>p.image)||SEED_PRODUCTS.find(p=>p.image);hero.src=(heroProduct&&heroProduct.image)||'';hero.alt=language==='en'?'Featured dish from Skina & Tomato':'طبق مميز من مطعم سكينة وطماطم';hero.onerror=()=>{if(hero.dataset.localFallback!=='1'){hero.dataset.localFallback='1';hero.src='assets/hero-food-fallback.svg';}else{hero.onerror=null;hero.classList.add('hero-image-unavailable');}};}renderPopular();if(popularTimer)clearInterval(popularTimer);const reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;if($('#popular-slides')&&!reduceMotion)popularTimer=setInterval(()=>shiftPopular(1),5000);}
  function renderMenu(){const grid=$('#menu-grid');if(!grid)return;const categoryBar=$('#category-filters')||$('#category-chips');if(categoryBar){const allLabel=language==='ar'?'كل التصنيفات':'All categories';const options=`<option value="all">${allLabel}</option>`+Object.entries(categories).map(([k,v])=>`<option value="${esc(k)}">${esc(language==='en'?(v.en||v.ar||k):(v.ar||v))}</option>`).join('');categoryBar.innerHTML=`<label class="category-select-label"><span>${language==='ar'?'تصفية حسب التصنيف':'Filter by category'}</span><select id="menu-category-select" aria-label="${allLabel}">${options}</select></label>`;const sel=$('#menu-category-select');if(sel)sel.value=activeCategory;}const results=products.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&(!searchTerm||[p.name,p.nameEn,p.description,p.descriptionEn,CATEGORIES[p.category],categories[p.category]?.en].filter(Boolean).join(' ').toLowerCase().includes(searchTerm.toLowerCase())));grid.innerHTML=results.map(productCard).join('');const empty=$('#menu-empty');if(empty)empty.classList.toggle('hidden',results.length>0);applyLanguage();}
  function renderTotals(prefix){const sub=$(`#${prefix}-subtotal`),del=$(`#${prefix}-delivery`),tot=$(`#${prefix}-total`);if(sub)sub.textContent=money(subtotal());if(del)del.textContent=money(delivery());if(tot)tot.textContent=money(total());}
  function renderCart(){const lines=$('#cart-lines');if(!lines)return;const rows=cartRows();const empty=$('#cart-empty');empty?.classList.toggle('hidden',rows.length>0);lines.innerHTML=rows.map(p=>`<div class="cart-row"><img class="cart-thumb" src="${esc(p.image||productImageFallback(p.category))}" data-fallback="${esc(productImageFallback(p.category))}" alt="${esc(p.name)}" loading="lazy" decoding="async" onerror="if(this.dataset.fallbackApplied!=='1'){this.dataset.fallbackApplied='1';this.src=this.dataset.fallback;}else{this.onerror=null;this.classList.add('image-failed');}"><div><div class="cart-title">${esc(p.name)}</div><div class="cart-desc">${hasDiscount(p)?`${money(p.price)} <del class="price-old">${money(p.originalPrice)}</del> للقطعة`:`${money(p.price)} للقطعة`}</div><div class="qty-control"><button data-action="qty" data-id="${esc(p.id)}" data-delta="-1" aria-label="تقليل الكمية">−</button><span>${p.qty}</span><button data-action="qty" data-id="${esc(p.id)}" data-delta="1" aria-label="زيادة الكمية">+</button></div></div><div class="cart-actions"><strong class="price">${money(p.price*p.qty)}</strong><button class="remove-link" data-action="remove" data-id="${esc(p.id)}">إزالة</button></div></div>`).join('');const n=$('#cart-item-count');if(n)n.textContent=`(${count()} صنف)`;renderTotals('cart');const checkout=$('#cart-checkout-link');if(checkout){checkout.classList.toggle('hidden',!rows.length);}const note=$('#delivery-note');if(note)note.textContent=Number(settings.freeDeliveryThreshold)>0&&subtotal()<Number(settings.freeDeliveryThreshold)?`أضف ${money(Number(settings.freeDeliveryThreshold)-subtotal())} لتحصل على توصيل مجاني (عرض تجريبي).`:'أنت مؤهل للتوصيل المجاني وفق إعدادات العرض.';}
  function renderPaymentDetails(){const method=$('input[name="payment"]:checked')?.value||'cash';const wrap=$('#digital-payment-details'),title=$('#digital-payment-title'),instructions=$('#digital-payment-instructions');if(!wrap||!title||!instructions)return;const refField=$('#payment-reference')?.closest('.field');if(refField)refField.classList.toggle('hidden',method==='visa');const isDigital=method==='cliq'||method==='electronic'||method==='visa';wrap.classList.toggle('hidden',!isDigital);if(!isDigital)return;if(method==='visa'){title.textContent='الدفع ببطاقة Visa';instructions.innerHTML=`<div class="visa-fields"><div class="field"><label for="visa-name">الاسم على البطاقة</label><input id="visa-name" autocomplete="cc-name" placeholder="كما يظهر على البطاقة"></div><div class="field"><label for="visa-number">رقم البطاقة</label><input id="visa-number" inputmode="numeric" autocomplete="cc-number" maxlength="23" placeholder="•••• •••• •••• ••••"></div><div class="visa-pair"><div class="field"><label for="visa-expiry">تاريخ الانتهاء</label><input id="visa-expiry" autocomplete="cc-exp" placeholder="MM/YY" maxlength="5"></div><div class="field"><label for="visa-cvv">رمز الأمان</label><input id="visa-cvv" inputmode="numeric" autocomplete="cc-csc" maxlength="4" placeholder="CVV"></div></div><p class="notice">واجهة تجريبية فقط: لا تدخل بيانات بطاقة حقيقية. لا تُرسل أو تُحفظ بيانات البطاقة، ولتفعيل Visa فعليًا يجب الربط ببوابة دفع معتمدة.</p></div>`;const reference=$('#payment-reference');if(reference)reference.closest('.field')?.classList.add('hidden');return;}if(method==='cliq'){title.textContent='تفاصيل التحويل عبر CliQ';instructions.innerHTML=`<div class="payment-info-row"><span>معرّف CliQ</span><strong dir="ltr">${esc(settings.cliqAlias||'لم يتم إعداد معرّف CliQ بعد')}</strong></div><div class="payment-info-row"><span>اسم المستفيد</span><strong>${esc(settings.cliqName||'لم يتم إدخال اسم المستفيد')}</strong></div>`;}else{title.textContent='تفاصيل الدفع الإلكتروني';instructions.innerHTML=`<div class="payment-info-row"><span>رقم الدفع / المحفظة</span><strong dir="ltr">${esc(settings.electronicPaymentNumber||'لم يتم إعداد رقم الدفع الإلكتروني بعد')}</strong></div>`;}}
  function renderCheckout(){const layout=$('#checkout-layout');if(!layout)return;const rows=cartRows();$('#checkout-empty')?.classList.toggle('hidden',rows.length>0);layout.classList.toggle('hidden',rows.length===0);const itemWrap=$('#checkout-summary-items');if(itemWrap)itemWrap.innerHTML=rows.map(p=>`<div class="summary-line"><span>${esc(p.name)} × ${p.qty}</span><strong>${money(p.price*p.qty)}</strong></div>`).join('');renderTotals('checkout');const checkoutDel=$('#checkout-delivery'),checkoutTot=$('#checkout-total');if(checkoutDel)checkoutDel.textContent=money(checkoutDelivery());if(checkoutTot)checkoutTot.textContent=money(subtotal()+checkoutDelivery());toggleAddress();renderPaymentDetails();}
  function toggleAddress(){const val=$('input[name="fulfillment"]:checked')?.value||'delivery';const f=$('#address-fields');if(f)f.classList.toggle('hidden',val!=='delivery');const address=$('#customer-address');const method=$('input[name="address-method"]:checked')?.value||'text';if(address)address.required=val==='delivery'&&method==='text';const textWrap=$('#address-text-wrap'),mapWrap=$('#address-map-wrap');if(textWrap)textWrap.classList.toggle('hidden',method!=='text');if(mapWrap)mapWrap.classList.toggle('hidden',method!=='map');if(val==='pickup'&&$('#checkout-delivery'))$('#checkout-delivery').textContent=money(0);if(val==='delivery'&&method==='map')setTimeout(()=>window.deliveryMap?.invalidateSize(),100);}
  function initDeliveryMap(){const el=$('#delivery-map');if(!el)return;if(!window.L){const status=$('#map-location-status');if(status)status.textContent='تعذر تحميل مكتبة الخريطة. أعد تحميل الصفحة أو استخدم كتابة العنوان.';return;}const map=L.map(el,{scrollWheelZoom:false}).setView([29.5267,35.0078],13);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>',updateWhenIdle:true,keepBuffer:2});let tileErrors=0;tiles.on('tileerror',()=>{tileErrors+=1;if(tileErrors>=2){const warning=$('#map-tile-warning');if(warning)warning.classList.remove('hidden');}});tiles.on('tileload',()=>{tileErrors=0;const warning=$('#map-tile-warning');if(warning)warning.classList.add('hidden');});tiles.addTo(map);let marker=null;const update=(latlng)=>{if(marker)marker.setLatLng(latlng);else marker=L.marker(latlng).addTo(map);$('#delivery-lat').value=latlng.lat.toFixed(6);$('#delivery-lng').value=latlng.lng.toFixed(6);$('#map-location-status').textContent=`تم تحديد الموقع: ${latlng.lat.toFixed(5)}, ${latlng.lng.toFixed(5)}`;$('#map-location-status').classList.add('location-selected');};map.on('click',e=>update(e.latlng));window.deliveryMap=map;const locate=$('#use-my-location');if(locate)locate.addEventListener('click',()=>{if(!navigator.geolocation){notify('المتصفح لا يدعم تحديد الموقع.');return;}locate.disabled=true;locate.textContent='جارٍ تحديد الموقع…';navigator.geolocation.getCurrentPosition(pos=>{const point={lat:pos.coords.latitude,lng:pos.coords.longitude};map.setView(point,16);update(point);locate.disabled=false;locate.textContent='استخدم موقعي الحالي';},()=>{notify('تعذر الوصول للموقع. يمكنك اختيار نقطة على الخريطة يدوياً.');locate.disabled=false;locate.textContent='استخدم موقعي الحالي';},{enableHighAccuracy:true,timeout:10000});});}

  function renderOrders(){const list=$('#orders-list');if(!list)return;const params=new URLSearchParams(location.search);const latest=params.get('new');const banner=$('#latest-order-banner');if(banner){const o=orders.find(x=>x.id===latest);const waSetup=false;banner.innerHTML=o?`<div class="success-banner"><div class="check">✓</div><div><strong>تم إنشاء الطلب التجريبي بنجاح</strong><span>رقم الطلب ${esc(o.id)} — يمكنك متابعة حالته في هذه الصفحة. لم يتم إرسال طلب حقيقي إلى المطعم.</span>${waSetup?'<span style="color:#96502c"> لم يُفتح واتساب لأن رقم المطعم غير مضبوط بعد. أضف الرقم من لوحة الإدارة ثم أعد المحاولة.</span>':''}</div></div>`:'';}const filtered=[...orders].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));list.innerHTML=filtered.map(o=>`<article class="order-card"><div class="order-top"><div><div class="order-id">${esc(o.id)}</div><div class="order-meta">${jordanDateText(o.createdAt,{dateStyle:'medium',timeStyle:'short'})} · ${esc(o.customer?.name||'عميل')}</div></div>${statusPill(o.status,o)}</div><div class="order-items">${(o.items||[]).map(i=>`${esc(i.name)} × ${Number(i.qty||i.quantity||1)}`).join('، ')}</div>${orderTracker(o)}<div class="order-foot"><div><span class="subtle">طريقة الاستلام: ${o.fulfillment==='pickup'?'استلام من المطعم':'توصيل'}</span><br><span class="subtle">${esc(o.customer?.phone||'')}</span></div><div><span class="subtle">الإجمالي</span><br><strong>${money(o.total)}</strong></div></div></article>`).join('');$('#orders-empty')?.classList.toggle('hidden',filtered.length>0);} 
  function adminSelect(id,status,order=null){const states=Object.entries(STATUS).filter(([value])=>!(order?.fulfillment==='pickup'&&value==='delivering')||value===status);return `<select class="admin-select" data-action="order-status" data-id="${esc(id)}" aria-label="تغيير حالة الطلب">${states.map(([value,label])=>`<option value="${value}" ${value===status?'selected':''}>${esc(order?orderStatusText({...order,status:value}):label)}</option>`).join('')}</select>`;}
  function adminOrderCard(o){return `<div class="admin-order-row"><div class="row-main"><strong>${esc(o.id)} · ${esc(o.customer?.name||'عميل')}</strong><span>${esc(o.customer?.phone||'لا يوجد هاتف')} · ${(o.items||[]).length} صنف · ${jordanDateText(o.createdAt,{dateStyle:'medium',timeStyle:'short'})}</span><span>${money(o.total)} · ${o.fulfillment==='pickup'?'استلام من المطعم':'توصيل'}</span></div><button class="btn btn-ghost btn-small" data-action="view-order" data-id="${esc(o.id)}">عرض الطلب</button>${statusPill(o.status,o)}${adminSelect(o.id,o.status,o)}</div>`;}
  function orderDetailsHtml(o){const items=o.items||[];const coords=o.coordinates;const address=o.fulfillment==='pickup'?'استلام من المطعم':(o.address||'لم يُسجّل عنوان');const mapLink=coords&&Number.isFinite(Number(coords.lat))&&Number.isFinite(Number(coords.lng))?`<a class="btn btn-ghost btn-small" href="https://www.google.com/maps?q=${encodeURIComponent(coords.lat+','+coords.lng)}" target="_blank" rel="noopener noreferrer">فتح الموقع على الخريطة ↗</a>`:'';return `<div class="order-detail-grid"><div class="order-detail-box"><span class="order-detail-label">اسم العميل</span><strong>${esc(o.customer?.name||'غير مسجل')}</strong></div><div class="order-detail-box"><span class="order-detail-label">رقم الهاتف</span><strong>${esc(o.customer?.phone||'غير مسجل')}</strong></div><div class="order-detail-box order-detail-wide"><span class="order-detail-label">عنوان التوصيل / الاستلام</span><strong>${esc(address)}</strong>${mapLink}</div><div class="order-detail-box order-detail-wide"><span class="order-detail-label">تفاصيل الأصناف</span>${items.length?`<div class="order-detail-items">${items.map(i=>`<div class="order-detail-item"><span>${esc(i.name)} <b>× ${Number(i.qty||i.quantity||1)}</b></span><strong>${money(Number(i.price||0)*Number(i.qty||i.quantity||1))}</strong></div>`).join('')}</div>`:'<p>لا توجد تفاصيل أصناف محفوظة.</p>'}</div><div class="order-detail-box order-detail-wide"><span class="order-detail-label">ملاحظات العميل</span><p class="order-detail-notes">${esc(o.notes||'لا توجد ملاحظات مضافة.')}</p></div><div class="order-detail-box"><span class="order-detail-label">طريقة الدفع</span><strong>${esc(({cash:'نقداً عند الاستلام',whatsapp:'عبر واتساب',card:'بطاقة',cliq:'CliQ',electronic:'رقم الدفع الإلكتروني'})[o.payment]||o.payment||'غير محددة')}</strong></div>${(o.payment==='cliq'||o.payment==='electronic')?`<div class="order-detail-box order-detail-wide"><span class="order-detail-label">تفاصيل التحويل / مرجع الدفع</span><p>${esc(o.paymentDetails?.recipient||o.paymentDetails?.number||'راجع إعدادات الدفع')}</p><p>مرجع العملية: ${esc(o.paymentReference||'لم يُدخل العميل مرجعاً')}</p><p>حالة الدفع: ${o.paymentStatus==='awaiting-transfer-review'?'بانتظار مراجعة المطعم':'غير محددة'}</p></div>`:''}<div class="order-detail-box"><span class="order-detail-label">تاريخ الطلب</span><strong>${new Date(o.createdAt).toLocaleString('ar-JO',{dateStyle:'medium',timeStyle:'short'})}</strong></div></div><div class="order-detail-totals"><div><span>المجموع الفرعي</span><strong>${money(o.subtotal??items.reduce((s,i)=>s+Number(i.price||0)*Number(i.qty||i.quantity||1),0))}</strong></div><div><span>رسوم التوصيل</span><strong>${money(o.delivery||0)}</strong></div><div class="order-detail-grand"><span>الإجمالي النهائي</span><strong>${money(o.total)}</strong></div></div>`;}
  function openOrderModal(id){const o=orders.find(x=>x.id===id);const modal=$('#order-modal');if(!o||!modal)return;$('#order-modal-title').textContent=`تفاصيل الطلب ${o.id}`;$('#order-modal-content').innerHTML=orderDetailsHtml(o);modal.dataset.orderId=o.id;modal.classList.add('open');}
  function closeOrderModal(){$('#order-modal')?.classList.remove('open');}
  function renderAdmin(){
    if(document.body.dataset.page!=='admin')return;
    const todayKey=jordanDateKey(new Date());
    const todayOrders=orders.filter(o=>Boolean(o?.createdAt)&&jordanDateKey(o.createdAt)===todayKey);
    const activeToday=todayOrders.filter(o=>!['completed','cancelled'].includes(o.status));
    const todayRevenue=todayOrders.filter(o=>o.status!=='cancelled').reduce((sum,o)=>sum+Number(o.total||0),0);
    const sortedToday=[...todayOrders].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
    const sortedAll=[...orders].sort((a,b)=>(new Date(b.createdAt).getTime()||0)-(new Date(a.createdAt).getTime()||0));
    const visibleOrders=adminOrderFilter==='today'?todayOrders:orders;
    const sortedVisible=adminOrderFilter==='today'?sortedToday:sortedAll;
    const todayLabel=jordanDateText(new Date(),{weekday:'long',year:'numeric',month:'long',day:'numeric'});
    const setText=(selector,value)=>{const el=$(selector);if(el)el.textContent=value;};
    setText('#overview-today-label',todayLabel);
    setText('#daily-focus-count',todayOrders.length);
    setText('#metric-orders',todayOrders.length);
    setText('#metric-active',activeToday.length);
    setText('#metric-revenue',Number(todayRevenue).toLocaleString('en-US',{maximumFractionDigits:0}));
    setText('#metric-products',products.length);
    setText('#orders-today-badge',todayOrders.length);
    setText('#orders-all-badge',orders.length);
    setText('#admin-order-count',`${visibleOrders.length} ${visibleOrders.length===1?'طلب معروض':'طلبات معروضة'}`);
    const todayTab=$('[data-action="order-filter"][data-filter="today"]');
    const allTab=$('[data-action="order-filter"][data-filter="all"]');
    [todayTab,allTab].forEach(button=>{if(button){const active=button.dataset.filter===adminOrderFilter;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active));}});
    setText('#orders-active-date',adminOrderFilter==='today'?`عرض طلبات ${todayLabel}`:'عرض السجل الكامل للطلبات');
    const overview=$('#overview-orders');
    if(overview){
      overview.innerHTML=sortedToday.length?sortedToday.slice(0,4).map(adminOrderCard).join(''):`<div class="daily-empty"><span class="daily-empty-icon" aria-hidden="true">☀</span><strong>يوم هادئ حتى الآن</strong><span>لا توجد طلبات أُنشئت اليوم. ستظهر الطلبات الجديدة هنا تلقائيًا.</span>${orders.length?'<button class="btn btn-ghost btn-small" data-action="show-all-orders">الاطّلاع على الطلبات السابقة</button>':''}</div>`;
    }
    const ordersList=$('#admin-orders-list');
    if(ordersList){
      ordersList.innerHTML=sortedVisible.length?sortedVisible.map(adminOrderCard).join(''):`<div class="daily-empty"><span class="daily-empty-icon" aria-hidden="true">${adminOrderFilter==='today'?'☀':'▤'}</span><strong>${adminOrderFilter==='today'?'لا توجد طلبات جديدة اليوم':'لا توجد طلبات مسجلة'}</strong><span>${adminOrderFilter==='today'?'غيّر العرض إلى «كل الطلبات» للوصول إلى الطلبات السابقة.':'ستظهر الطلبات هنا عند إنشاء أول طلب من واجهة العميل.'}</span>${adminOrderFilter==='today'&&orders.length?'<button class="btn btn-ghost btn-small" data-action="order-filter" data-filter="all">عرض كل الطلبات</button>':''}</div>`;
    }
    const categorySelect=$('#product-category');if(categorySelect){const selected=categorySelect.value;categorySelect.innerHTML=Object.entries(categories).map(([k,v])=>`<option value="${esc(k)}">${esc(v.ar||v)}</option>`).join('');if(categories[selected])categorySelect.value=selected;} const categoryList=$('#admin-categories-list');if(categoryList)categoryList.innerHTML=Object.entries(categories).map(([key,val])=>`<div class="admin-product-row category-row"><div class="row-main"><strong>${esc(val.ar||val)}</strong><span>${esc(val.en||'لا يوجد اسم إنجليزي')}</span></div><button class="btn btn-danger btn-small" data-action="delete-category" data-id="${esc(key)}" ${Object.values(products).some(p=>p.category===key)?'disabled title="هذا التصنيف مستخدم في أصناف"':''}>حذف</button></div>`).join('');$('#admin-products-list').innerHTML=products.map(p=>`<div class="admin-product-row"><img class="admin-mini-image" src="${esc(p.image||productImageFallback(p.category))}" data-fallback="${esc(productImageFallback(p.category))}" alt="" loading="lazy" decoding="async" onerror="if(this.dataset.fallbackApplied!=='1'){this.dataset.fallbackApplied='1';this.src=this.dataset.fallback;}else{this.onerror=null;this.classList.add('image-failed');}"><div class="row-main"><strong>${esc(p.name)}</strong><span>${esc(language==='en'?(categories[p.category]?.en||categories[p.category]?.ar||'Selected dishes'):(CATEGORIES[p.category]||'أطباق مختارة'))} · ${p.available?'متاح للطلب':'غير متاح'}</span><span>${esc(p.description||'')}</span></div><div class="row-price">${hasDiscount(p)?`<span class="price-current">${money(discountedPrice(p))}</span><br><del class="price-old">${money(p.price)}</del>`:money(p.price)}</div><div class="product-actions" style="display:flex;gap:7px"><button class="btn btn-ghost btn-small" data-action="edit-product" data-id="${esc(p.id)}">تعديل</button><button class="btn btn-small ${p.available?'btn-soft':'btn-primary'}" data-action="toggle-product" data-id="${esc(p.id)}">${p.available?'إيقاف':'تفعيل'}</button></div></div>`).join('');const f=$('#settings-form');if(f){f.elements.whatsappNumber.value=settings.whatsappNumber||'';if(f.elements.phoneNumber)f.elements.phoneNumber.value=settings.phoneNumber||'';if(f.elements.email)f.elements.email.value=settings.email||'';if(f.elements.cliqAlias)f.elements.cliqAlias.value=settings.cliqAlias||'';if(f.elements.cliqName)f.elements.cliqName.value=settings.cliqName||'';if(f.elements.electronicPaymentNumber)f.elements.electronicPaymentNumber.value=settings.electronicPaymentNumber||'';f.elements.deliveryFee.value=Number(settings.deliveryFee||0);f.elements.freeDeliveryThreshold.value=Number(settings.freeDeliveryThreshold||0);f.elements.currency.value=settings.currency||'ر.س';}}
  function addToCart(id){const p=productById(id);if(!p||!p.available){notify('هذا الصنف غير متاح حالياً.');return;}const found=cart.find(c=>c.id===id);if(found)found.qty+=1;else cart.push({id,qty:1});saveCart();renderGlobal();renderCart();renderCheckout();notify(`تمت إضافة «${p.name}» إلى السلة.`);}
  function updateQty(id,delta){const row=cart.find(c=>c.id===id);if(!row)return;row.qty+=Number(delta);if(row.qty<=0)cart=cart.filter(c=>c.id!==id);saveCart();renderGlobal();renderCart();renderCheckout();}
  function clearCart(){cart=[];saveCart();renderGlobal();renderCart();renderCheckout();notify('تم إفراغ السلة.');}
  function openWhatsApp(topic){const number=String(settings.whatsappNumber||'').replace(/\D/g,'');const current=cartRows();let message='مرحباً '+BRAND_NAME+'، ';if(topic==='order'){message+='أرغب بمتابعة طلبي. ';if(current.length){message+='تفاصيل السلة: '+current.map(i=>`${i.name} × ${i.qty}`).join('، ')+'. الإجمالي التقريبي '+money(total())+'.';}else{message+='أرغب بمعرفة طريقة تقديم الطلب.';}}else if(topic==='menu'){message+='أود الاستفسار عن قائمة الطعام والأسعار والتوفر.';}else{message+='أرغب بالتواصل مع فريق المطعم من فضلكم.';}if(!number){const err=$('#chat-error');if(err)err.textContent='لم يتم إعداد رقم واتساب بعد. افتح لوحة الإدارة ← إعدادات المطعم، وأدخل الرقم مع رمز الدولة ثم احفظ الإعدادات.';notify('أضف رقم واتساب المطعم من لوحة الإدارة أولاً.');return;}if(number.length<9){notify('رقم واتساب يبدو غير مكتمل. راجعه من لوحة الإدارة.');return;}const url=`https://wa.me/${number}?text=${encodeURIComponent(message)}`;window.open(url,'_blank','noopener,noreferrer');const err=$('#chat-error');if(err)err.textContent='تم تجهيز الرسالة. أكمل الإرسال من تطبيق واتساب بعد فتح المحادثة.';}
  function openWhatsAppForOrder(order){const number=String(settings.whatsappNumber||'').replace(/\D/g,'');if(number.length<9)return false;const details=(order.items||[]).map(i=>`${i.name} × ${i.qty}`).join('، ');const msg=`مرحباً ${BRAND_NAME}، أرسل تفاصيل طلبي التجريبي رقم ${order.id}. الأصناف: ${details}. الإجمالي: ${money(order.total)}. الاسم: ${order.customer.name}، الهاتف: ${order.customer.phone}، طريقة الاستلام: ${order.fulfillment==='pickup'?'استلام من المطعم':'توصيل'}${order.address?'، العنوان: '+order.address:''}.`;window.open(`https://wa.me/${number}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer');return true;}
  function printMenu(){
    const items=products.filter(p=>p.available!==false);
    const rows=items.map(p=>`<article class="item"><img src="${esc(p.image||productImageFallback(p.category))}" data-fallback="${esc(productImageFallback(p.category))}" alt="${esc(p.name)}" onerror="if(this.dataset.fallbackApplied!=='1'){this.dataset.fallbackApplied='1';this.src=this.dataset.fallback;}else{this.onerror=null;this.style.visibility='hidden';}"><div class="item-info"><h2>${esc(p.name)}</h2><p>${esc(categories[p.category]?.ar||p.category||'')}</p></div><strong>${money(p.price)}</strong></article>`).join('');
    const w=window.open('','_blank');
    if(!w){notify('يرجى السماح بالنوافذ المنبثقة لإنشاء قائمة الطعام القابلة للطباعة.');return;}
    w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="${esc(new URL('.',location.href).href)}"><title>قائمة الطعام - ${esc(BRAND_NAME)}</title><style>*{box-sizing:border-box}body{font-family:Arial,Tahoma,sans-serif;color:#243e34;margin:0;padding:28px;background:#fff}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #243e34;padding-bottom:18px;margin-bottom:20px}.head h1{margin:0 0 6px;font-size:28px}.head p{margin:0;color:#66756c}.actions{display:flex;gap:8px;margin-bottom:18px}.actions button{border:0;border-radius:8px;padding:10px 16px;background:#243e34;color:#fff;cursor:pointer}.items{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.item{display:flex;align-items:center;gap:12px;border:1px solid #d9e0da;border-radius:10px;padding:10px;break-inside:avoid;min-width:0}.item img{width:94px;height:84px;object-fit:cover;border-radius:7px;background:#eef1ed;flex-shrink:0}.item-info{flex:1;min-width:0}.item h2{font-size:15px;margin:0 0 6px}.item p{font-size:12px;color:#65736a;margin:0}.item strong{white-space:nowrap;font-size:14px}.foot{margin-top:22px;border-top:1px solid #ddd;padding-top:10px;color:#777;font-size:11px}@media(max-width:600px){.items{grid-template-columns:1fr}.head h1{font-size:22px}}@media print{body{padding:0}.actions{display:none}.item{border-color:#bbb}.items{gap:8px}@page{size:A4;margin:12mm}}</style></head><body><header class="head"><div><h1>${esc(BRAND_NAME)}</h1><p>قائمة الطعام · الأسعار بالعملة المعتمدة لدى المطعم</p></div><div>${new Date().toLocaleDateString('ar-JO')}</div></header><div class="actions"><button onclick="window.print()">طباعة / حفظ كـ PDF</button><button onclick="window.close()">إغلاق</button></div><main class="items">${rows||'<p>لا توجد أصناف متاحة حالياً.</p>'}</main><footer class="foot">تم إنشاء هذه القائمة من بيانات العرض التجريبي. ${items.length} صنفاً متاحاً.</footer></body></html>`);
    w.document.close();
  }
  function changeAdminTab(tab){$$('[data-admin-tab]').forEach(el=>el.classList.toggle('active',el.dataset.adminTab===tab));$$('.admin-section').forEach(el=>el.classList.toggle('active',el.id===`admin-${tab}`));if(location.hash!==`#${tab}`)history.replaceState(null,'',`#${tab}`);}
  function openProductModal(id){const modal=$('#product-modal'), form=$('#product-form');if(!modal||!form)return;form.reset();const p=id?productById(id):null;$('#product-modal-title').textContent=p?'تعديل الصنف':'إضافة صنف جديد';form.elements.id.value=p?.id||'';form.elements.name.value=p?.name||'';if(form.elements.nameEn)form.elements.nameEn.value=p?.nameEn||'';if(form.elements.descriptionEn)form.elements.descriptionEn.value=p?.descriptionEn||'';form.elements.price.value=p?.price??'';form.elements.discountType.value=p?.discountType||'none';form.elements.discountValue.value=p?.discountValue??0;form.elements.category.value=p?.category||'mains';form.elements.description.value=p?.description||'';form.elements.image.value=p?.image||'';form.elements.available.checked=p?p.available!==false:true;$('#delete-product-button')?.classList.toggle('hidden',!p);modal.classList.add('open');}
  function closeProductModal(){$('#product-modal')?.classList.remove('open');}
  document.addEventListener('click',(e)=>{
    const cat=e.target.closest('[data-category]');if(cat){activeCategory=cat.dataset.category;renderMenu();return;}
    const tab=e.target.closest('[data-admin-tab]');if(tab){e.preventDefault();changeAdminTab(tab.dataset.adminTab);return;}
    const nav=e.target.closest('[data-action]');if(!nav)return;const action=nav.dataset.action,id=nav.dataset.id;
    if(action==='toggle-language'){language=language==='ar'?'en':'ar';localStorage.setItem(KEYS.language,language);renderGlobal();renderHome();renderMenu();renderCart();renderCheckout();renderOrders();renderAdmin();return;}
    else if(action==='print-menu'){printMenu();return;}
    else if(action==='popular-next'){shiftPopular(1);return;}
    else if(action==='popular-prev'){shiftPopular(-1);return;}
    else if(action==='popular-go'){popularIndex=Number(nav.dataset.index||0);renderPopular();return;}
    else if(action==='order-filter'){adminOrderFilter=nav.dataset.filter==='all'?'all':'today';renderAdmin();return;}
    else if(action==='show-all-orders'){adminOrderFilter='all';changeAdminTab('orders');renderAdmin();return;}
    else if(action==='view-order'){openOrderModal(id);return;}
    else if(action==='close-order-modal'){closeOrderModal();return;}
    else if(action==='add')addToCart(id);
    else if(action==='qty')updateQty(id,Number(nav.dataset.delta||0));
    else if(action==='remove'){cart=cart.filter(c=>c.id!==id);saveCart();renderGlobal();renderCart();renderCheckout();notify('تمت إزالة الصنف من السلة.');}
    else if(action==='clear-cart')clearCart();
    else if(action==='reset-menu'){activeCategory='all';searchTerm='';const input=$('#menu-search');if(input)input.value='';renderMenu();}
    else if(action==='chat-toggle'){$('#chat-panel')?.classList.toggle('open');}
    else if(action==='chat-topic')openWhatsApp(nav.dataset.topic);
    else if(action==='mobile-nav')$('#mobile-nav-links')?.classList.toggle('hidden');
    else if(action==='new-product')openProductModal();
    else if(action==='edit-product')openProductModal(id);
    else if(action==='delete-product'){const p=productById($('#product-id')?.value||id);if(p&&confirm(`هل تريد حذف الصنف «${p.name}» نهائياً من قائمة الطعام؟`)){products=products.filter(x=>x.id!==p.id);cart=cart.filter(x=>x.id!==p.id);saveProducts();saveCart();closeProductModal();refreshAll();notify('تم حذف الصنف من قائمة الطعام.');}return;}
    else if(action==='delete-category'){if(Object.values(products).some(p=>p.category===id)){notify('لا يمكن حذف تصنيف مستخدم في أحد الأصناف.');return;}if(categories[id]&&confirm('هل تريد حذف هذا التصنيف؟')){delete categories[id];write(KEYS.categories,categories);renderAdmin();renderMenu();notify('تم حذف التصنيف.');}return;}
    else if(action==='close-product-modal')closeProductModal();
    else if(action==='toggle-product'){const p=productById(id);if(p){p.available=!p.available;saveProducts();refreshAll();notify(p.available?'تم تفعيل الصنف.':'تم إيقاف الصنف.');}}
    else if(action==='test-whatsapp')openWhatsApp('staff');
  });
  document.addEventListener('click',(e)=>{const backdrop=e.target.closest('#order-modal');if(backdrop&&e.target===backdrop)closeOrderModal();});
  document.addEventListener('keydown',(e)=>{if(e.key==='Escape')closeOrderModal();});
  document.addEventListener('input',(e)=>{if(e.target.id==='menu-search'){searchTerm=e.target.value||'';renderMenu();}});
  document.addEventListener('change',(e)=>{if(e.target.id==='menu-category-select'){activeCategory=e.target.value||'all';renderMenu();}});
  document.addEventListener('change',(e)=>{if(e.target.matches('input[name="fulfillment"]')){toggleAddress();renderCheckout();}if(e.target.matches('input[name="address-method"]'))toggleAddress();if(e.target.matches('input[name="payment"]'))renderPaymentDetails();if(e.target.matches('[data-action="order-status"]')){const order=orders.find(o=>o.id===e.target.dataset.id);if(order){order.status=e.target.value;saveOrders();renderAdmin();renderOrders();notify('تم تحديث حالة الطلب.');}}});
  const contactForm=$('#contact-form');if(contactForm)contactForm.addEventListener('submit',(e)=>{e.preventDefault();const fd=new FormData(contactForm);const recipient=String(settings.email||'').trim();const name=String(fd.get('contactName')||'').trim();const replyEmail=String(fd.get('contactReplyEmail')||'').trim();const topic=String(fd.get('contactTopic')||'استفسار عام').trim();const message=String(fd.get('contactMessage')||'').trim();const note=$('#contact-form-note');if(!recipient||!recipient.includes('@')){if(note)note.textContent='لم يتم إعداد بريد إلكتروني صحيح للمطعم بعد. يرجى استخدام واتساب أو الاتصال، أو إعداد البريد من لوحة الإدارة.';notify('لم يتم إعداد بريد إلكتروني صالح للمطعم.');return;}const subject=`${topic} — ${name}`;const body=`الاسم: ${name}\\nبريد العميل: ${replyEmail}\\nنوع الاستفسار: ${topic}\\n\\nتفاصيل الرسالة:\\n${message}`;const mailto=`mailto:${recipient}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;if(note)note.textContent='تم تجهيز الرسالة. أكّد الإرسال من تطبيق البريد الإلكتروني الذي سيفتح الآن.';window.location.href=mailto;});
  const checkoutForm=$('#checkout-form');if(checkoutForm)checkoutForm.addEventListener('submit',(e)=>{e.preventDefault();if(!cartRows().length){notify('أضف صنفاً إلى السلة أولاً.');return;}const fd=new FormData(checkoutForm);const selectedPayment=String(fd.get('payment')||'cash');if(selectedPayment==='cliq'&&!String(settings.cliqAlias||'').trim()){notify('لم يُضف المطعم معرّف CliQ بعد. يرجى التواصل مع المطعم أو اختيار طريقة دفع أخرى.');return;}if(selectedPayment==='visa'){const card=$('#visa-number')?.value.replace(/\D/g,'')||'';const exp=$('#visa-expiry')?.value.trim()||'';const cvv=$('#visa-cvv')?.value.trim()||'';if(!$('#visa-name')?.value.trim()||card.length<13||!/^\d{2}\/\d{2}$/.test(exp)||cvv.length<3){notify('أدخل بيانات بطاقة تجريبية صحيحة لإكمال العرض، ولا تستخدم بطاقة حقيقية.');return;}}if(selectedPayment==='electronic'&&!String(settings.electronicPaymentNumber||'').trim()){notify('لم يُضف المطعم رقم الدفع الإلكتروني بعد. يرجى التواصل مع المطعم أو اختيار طريقة دفع أخرى.');return;}const fulfillment=fd.get('fulfillment')||'delivery';const addressMethod=String(fd.get('address-method')||'text');let address=String(fd.get('address')||'').trim();const lat=String($('#delivery-lat')?.value||''),lng=String($('#delivery-lng')?.value||'');if(fulfillment==='delivery'&&addressMethod==='map'){if(!lat||!lng){notify('حدد موقع التوصيل على الخريطة أولاً.');return;}address=`موقع على الخريطة: ${lat}, ${lng}`;}if(fulfillment==='delivery'&&addressMethod==='text'&&!address){$('#customer-address')?.focus();notify('أدخل عنوان التوصيل للمتابعة.');return;}const items=cartRows().map(p=>({id:p.id,name:p.name,price:Number(p.price),qty:p.qty}));const id='GOS-'+String(Date.now()).slice(-7);const order={id,createdAt:new Date().toISOString(),customer:{name:String(fd.get('name')||'').trim(),phone:String(fd.get('phone')||'').trim()},fulfillment,address:fulfillment==='delivery'?address:'استلام من المطعم',addressMethod:fulfillment==='delivery'?addressMethod:'pickup',coordinates:fulfillment==='delivery'&&addressMethod==='map'?{lat:Number(lat),lng:Number(lng)}:null,payment:selectedPayment,paymentStatus:(selectedPayment==='cliq'||selectedPayment==='electronic')?'awaiting-transfer-review':(selectedPayment==='visa'?'demo-card-not-charged':'not-applicable'),paymentReference:String(fd.get('paymentReference')||'').trim(),paymentCardLast4:selectedPayment==='visa'?String($('#visa-number')?.value.replace(/\D/g,'').slice(-4)||''):null,paymentDetails:(fd.get('payment')==='cliq'?{recipient:settings.cliqAlias||'',name:settings.cliqName||''}:(fd.get('payment')==='electronic'?{number:settings.electronicPaymentNumber||''}:null)),notes:String(fd.get('notes')||'').trim(),items,subtotal:subtotal(),delivery:fulfillment==='pickup'?0:delivery(),total:subtotal()+(fulfillment==='pickup'?0:delivery()),status:'received'};orders.push(order);saveOrders();cart=[];saveCart();renderGlobal();location.href=`orders.html?new=${encodeURIComponent(id)}`;});
  const categoryForm=$('#category-form');if(categoryForm)categoryForm.addEventListener('submit',(e)=>{e.preventDefault();const fd=new FormData(categoryForm);const name=String(fd.get('name')||'').trim();const englishName=String(fd.get('nameEn')||'').trim();const baseKey=(englishName.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||`category-${Date.now()}`);let key=baseKey,n=2;while(categories[key])key=`${baseKey}-${n++}`;categories[key]={ar:name,en:englishName||name};write(KEYS.categories,categories);categoryForm.reset();renderAdmin();renderMenu();notify('تمت إضافة التصنيف بنجاح.');});
  const settingsForm=$('#settings-form');if(settingsForm)settingsForm.addEventListener('submit',(e)=>{e.preventDefault();const fd=new FormData(settingsForm);settings={...settings,restaurantName:BRAND_NAME,whatsappNumber:String(fd.get('whatsappNumber')||'').replace(/\D/g,''),phoneNumber:String(fd.get('phoneNumber')||'').trim(),email:String(fd.get('email')||'').trim(),cliqAlias:String(fd.get('cliqAlias')||'').trim(),cliqName:String(fd.get('cliqName')||'').trim(),electronicPaymentNumber:String(fd.get('electronicPaymentNumber')||'').trim(),deliveryFee:Math.max(0,Number(fd.get('deliveryFee')||0)),freeDeliveryThreshold:Math.max(0,Number(fd.get('freeDeliveryThreshold')||0)),currency:String(fd.get('currency')||'ر.س')};write(KEYS.settings,settings);renderGlobal();renderCart();renderCheckout();renderAdmin();notify('تم حفظ إعدادات المطعم على هذا المتصفح.');});
  const productForm=$('#product-form');if(productForm)productForm.addEventListener('submit',(e)=>{e.preventDefault();const fd=new FormData(productForm);const id=String(fd.get('id')||'').trim()||`custom-${Date.now()}`;const existing=productById(id);const discountType=String(fd.get('discountType')||'none');const discountValue=discountType==='none'?0:Math.max(0,Number(fd.get('discountValue')||0));const item={id,name:String(fd.get('name')||'').trim(),nameEn:String(fd.get('nameEn')||'').trim(),descriptionEn:String(fd.get('descriptionEn')||'').trim(),price:Math.max(0,Number(fd.get('price')||0)),discountType:discountType==='none'?'none':discountType,discountValue:discountType==='percent'?Math.min(100,discountValue):discountValue,category:String(fd.get('category')||'mains'),description:String(fd.get('description')||'').trim(),image:String(fd.get('image')||'').trim(),available:$('#product-available').checked,featured:existing?.featured||false};if(existing)products=products.map(p=>p.id===id?item:p);else products.push(item);saveProducts();closeProductModal();refreshAll();notify('تم حفظ الصنف، وتم تحديث قائمة الطعام.');});
  function refreshAll(){products=read(KEYS.products,SEED_PRODUCTS);cart=read(KEYS.cart,[]);orders=read(KEYS.orders,[]);settings={...DEFAULT_SETTINGS,...read(KEYS.settings,DEFAULT_SETTINGS)};categories={...DEFAULT_CATEGORIES,...read(KEYS.categories,{})};renderGlobal();renderHome();renderMenu();renderCart();renderCheckout();renderOrders();renderAdmin();}
  function init(){renderGlobal();renderHome();renderMenu();renderCart();renderCheckout();renderOrders();renderAdmin();initDeliveryMap();const page=document.body.dataset.page;if(page==='admin'){const initial=location.hash.replace('#','');if(['overview','orders','products','categories','settings'].includes(initial))changeAdminTab(initial);}}
